758	function Get-NextNumbers {
759	    param($Consults, $Store, [string]$HandoffsDir, [Alias('Leftover')] [object[]]$Leftovers = @())
760	    $ledgerNs = @{}
761	    $maxN = @($Consults).Count
762	    foreach ($c in @($Consults | Where-Object { $null -ne $_ })) {
763	        $v = 0
764	        if ($c.PSObject.Properties['n'] -and [int]::TryParse([string]$c.n, [ref]$v)) {
765	            $ledgerNs[$v] = $true
766	            if ($v -gt $maxN) { $maxN = $v }
767	        }
768	    }
769	    $maxNn = 0
770	    if ($HandoffsDir -and (Test-Path -LiteralPath $HandoffsDir)) {
771	        foreach ($file in @(Get-ChildItem -LiteralPath $HandoffsDir -File -ErrorAction SilentlyContinue)) {
772	            $v = 0
773	            if ($file.Name -match '^(\d{2,})-' -and [int]::TryParse($Matches[1], [ref]$v) -and $v -gt $maxNn) { $maxNn = $v }
774	        }
775	    }
776	    if ($Store) {
777	        foreach ($f in @($Store.findings | Where-Object { $null -ne $_ })) {
778	            $v = 0
779	            $src = Get-PropertyValue $f 'source' $null
780	            if ($src -and [int]::TryParse([string](Get-PropertyValue $src 'consult' ''), [ref]$v) -and $v -gt $maxN) { $maxN = $v }
781	            foreach ($rc in @(Get-PropertyValue $f 'reviewer_checks' @())) {
782	                $v = 0
783	                if ($rc -and [int]::TryParse([string](Get-PropertyValue $rc 'consult' ''), [ref]$v) -and $v -gt $maxN) { $maxN = $v }
784	            }
785	            $v = 0
786	            if ([string](Get-PropertyValue $f 'id' '') -match '^F(\d{2,})-\d+$' -and [int]::TryParse($Matches[1], [ref]$v) -and $v -gt $maxNn) { $maxNn = $v }
787	        }
788	    }
789	    $items = New-Object System.Collections.Generic.List[object]
790	    foreach ($leftover in @($Leftovers | Where-Object { $null -ne $_ })) {
791	        $recovered = $false
792	        $recN = $null
793	        $recNn = ''
794	        $v = 0
795	        if ([int]::TryParse([string](Get-PropertyValue $leftover 'n' ''), [ref]$v) -and $v -gt 0) {
796	            $recN = $v
797	            if (-not $ledgerNs.ContainsKey($v)) { $recovered = $true }
798	            if ($v -gt $maxN) { $maxN = $v }
799	        }
800	        $w = 0
801	        $leftNn = [string](Get-PropertyValue $leftover 'nn' '')
802	        if ($leftNn -and [int]::TryParse($leftNn, [ref]$w) -and $w -gt 0) {
803	            $recNn = $leftNn
