805	            if ($null -eq $recN) { $recovered = $true }
806	        }
807	        $items.Add([pscustomobject]@{ N = $recN; Nn = $recNn; Recovered = $recovered })
808	    }
809	    $first = if ($items.Count -gt 0) { $items[0] } else { [pscustomobject]@{ N = $null; Nn = ''; Recovered = $false } }
810	    return [pscustomobject]@{
811	        N           = $maxN + 1
812	        Nn          = ('{0:D2}' -f ($maxNn + 1))
813	        Recovered   = [bool](@($items | Where-Object { $_.Recovered }).Count -gt 0)
814	        RecoveredN  = $first.N
815	        RecoveredNn = $first.Nn
816	        Items       = [object[]]$items.ToArray()
817	    }
