4187	function Get-PanelPlan {
4188	    param([object[]]$Runners, [hashtable]$Parallel = $null, [int]$Cap = 0)
4189	    $labels = New-Object System.Collections.Generic.List[string]
4190	    $fps = New-Object System.Collections.Hashtable ([StringComparer]::Ordinal)
4191	    foreach ($m in @($Runners | Where-Object { $_ })) {
4192	        $label = [string]$m.Entry.Provider
4193	        if (-not $fps.ContainsKey($label)) { $fps[$label] = New-Object System.Collections.Generic.List[string]; $labels.Add($label) }
4194	        $fp = ''
4195	        if ($m.Identity -and $m.Identity.Resolved) { $fp = [string]$m.Identity.Fingerprint }
4196	        if ($fp -and -not $fps[$label].Contains($fp)) { $fps[$label].Add($fp) }
4197	    }
4198	    # one group per label, then labels that share a fingerprint are merged (to a fixed point)
4199	    $groupOfLabel = New-Object System.Collections.Hashtable ([StringComparer]::Ordinal)
4200	    for ($i = 0; $i -lt $labels.Count; $i++) { $groupOfLabel[$labels[$i]] = $i }
4201	    $changed = $true
4202	    while ($changed) {
4203	        $changed = $false
4204	        for ($i = 0; $i -lt $labels.Count; $i++) {
4205	            for ($j = $i + 1; $j -lt $labels.Count; $j++) {
4206	                $gi = $groupOfLabel[$labels[$i]]; $gj = $groupOfLabel[$labels[$j]]
4207	                if ($gi -eq $gj) { continue }
4208	                $shared = @($fps[$labels[$i]] | Where-Object { $fps[$labels[$j]].Contains($_) }).Count -gt 0
4209	                if (-not $shared) { continue }
4210	                $keep = [Math]::Min($gi, $gj); $drop = [Math]::Max($gi, $gj)
4211	                foreach ($l in $labels) { if ($groupOfLabel[$l] -eq $drop) { $groupOfLabel[$l] = $keep } }
4212	                $changed = $true
4213	            }
4214	        }
4215	    }
4216	    $groups = New-Object System.Collections.Generic.List[object]
4217	    $indexOf = @{}
4218	    $groupOf = @{}
4219	    foreach ($m in @($Runners | Where-Object { $_ })) {
4220	        $label = [string]$m.Entry.Provider
4221	        $gid = $groupOfLabel[$label]
4222	        if (-not $indexOf.ContainsKey($gid)) {
4223	            $indexOf[$gid] = $groups.Count
4224	            $groups.Add([pscustomobject]@{ Labels = (New-Object System.Collections.Generic.List[string]); Limit = 0; Positions = (New-Object System.Collections.Generic.List[int]) })
4225	        }
4226	        $g = $groups[$indexOf[$gid]]
4227	        if (-not $g.Labels.Contains($label)) { $g.Labels.Add($label) }
4228	        $g.Positions.Add([int]$m.Entry.Position)
4229	        $groupOf[[int]$m.Entry.Position] = $indexOf[$gid]
4230	    }
4231	    $effective = 0
4232	    $limits = [ordered]@{}
4233	    $out = New-Object System.Collections.Generic.List[object]
4234	    foreach ($g in $groups) {
4235	        $limit = 0
4236	        foreach ($l in $g.Labels) {
4237	            $v = 1
4238	            if ($null -ne $Parallel -and $Parallel.ContainsKey($l)) { $v = [int]$Parallel[$l] }
4239	            if ($limit -eq 0 -or $v -lt $limit) { $limit = $v }
4240	        }
4241	        $effective += [Math]::Min($limit, $g.Positions.Count)
4242	        $out.Add([pscustomobject]@{ Labels = [string[]]$g.Labels.ToArray(); Limit = $limit; Positions = [int[]]$g.Positions.ToArray() })
4243	    }
4244	    foreach ($l in $labels) { $limits[$l] = $out[$indexOf[$groupOfLabel[$l]]].Limit }
4245	    if ($Cap -gt 0 -and $Cap -lt $effective) { $effective = $Cap }
4246	    $count = @($Runners | Where-Object { $_ }).Count
4247	    $text = if ($effective -ge $count) { 'at once' } elseif ($effective -le 1) { 'one after another' } else { "at most $effective at a time" }
4248	    return [pscustomobject]@{ Groups = [object[]]$out.ToArray(); GroupOf = $groupOf; Cap = $Cap; Effective = $effective; Text = $text; Limits = $limits }
4249	}
