4654	function Enter-WriteLock {
4655	    param([string]$TaskDir, [string]$Task, [double]$TimeoutSec = 60)
4656	    $path = Join-Path $TaskDir '.consult.write.lock'
4657	    $share = if ($script:OnWindows) { [IO.FileShare]::Read } else { [IO.FileShare]::None }
4658	    $record = [pscustomobject]@{
4659	        pid        = $PID
4660	        start_time = (Get-ProcessStartIso -ProcessId $PID)
4661	        host       = [Environment]::MachineName
4662	        task       = $Task
4663	        started    = (Get-IsoTimestamp)
4664	    }
4665	    $watch = [System.Diagnostics.Stopwatch]::StartNew()
4666	    $delay = 50
4667	    $fs = $null
4668	    while ($null -eq $fs) {
4669	        try {
4670	            $fs = [IO.File]::Open($path, [IO.FileMode]::OpenOrCreate, [IO.FileAccess]::ReadWrite, $share)
4671	        } catch [System.IO.DirectoryNotFoundException] {
4672	            $r = New-LockRefusal -Path $path -Message "could not open the write lock '$path': $($_.Exception.Message)"
4673	            $r | Add-Member -NotePropertyName 'Waited' -NotePropertyValue ([math]::Round($watch.Elapsed.TotalSeconds, 1))
4674	            return $r
4675	        } catch [System.IO.IOException] {
4676	            if ($watch.Elapsed.TotalSeconds -ge $TimeoutSec) {
4677	                $who = 'a live process'
4678	                $holder = Read-LockContent -Path $path
4679	                $hpid = 0
4680	                if ($holder -and [int]::TryParse([string](Get-PropertyValue $holder 'pid' ''), [ref]$hpid) -and
4681	                    (Test-PidAlive -ProcessId $hpid -StartTime (ConvertTo-JsonText (Get-PropertyValue $holder 'start_time' '')))) {
4682	                    $who = "pid $hpid on $(Get-PropertyValue $holder 'host' '?') since $(Get-PropertyValue $holder 'started' '?')"
4683	                }
4684	                $r = New-LockRefusal -Path $path -Message "the write lock '$path' of task '$Task' was not acquired within $TimeoutSec s: it is held open by $who"
4685	                $r | Add-Member -NotePropertyName 'Waited' -NotePropertyValue ([math]::Round($watch.Elapsed.TotalSeconds, 1))
4686	                return $r
4687	            }
4688	            Start-Sleep -Milliseconds $delay
4689	            $delay = [Math]::Min($delay * 2, 1000)
4690	        } catch {
4691	            $r = New-LockRefusal -Path $path -Message "could not open the write lock '$path': $($_.Exception.Message)"
4692	            $r | Add-Member -NotePropertyName 'Waited' -NotePropertyValue ([math]::Round($watch.Elapsed.TotalSeconds, 1))
4693	            return $r
4694	        }
4695	    }
4696	    # Informational only (who holds it); nothing recoverable lives here.
4697	    try {
4698	        $bytes = $script:Utf8NoBom.GetBytes((ConvertTo-Json -InputObject $record -Compress) + "`n")
4699	        $fs.SetLength(0)
4700	        $fs.Position = 0
4701	        $fs.Write($bytes, 0, $bytes.Length)
4702	        $fs.Flush($true)
4703	    } catch { }
4704	    return [pscustomobject]@{ Acquired = $true; Path = $path; Stream = $fs; Record = $record; Message = ''; Waited = [math]::Round($watch.Elapsed.TotalSeconds, 1) }
4705	}
